# Dataset has no guild names, only ids — map known ones here.
GUILD_NAMES = {
    "1493402605504823357": "Glint Research",
}


def guild_display_name(guild_id: str) -> str:
    return GUILD_NAMES.get(guild_id, f"Server {guild_id[-4:]}")


# ---------------------------------------------------------------------------
# Indexes (rebuilt on refresh)
# ---------------------------------------------------------------------------
def build_indexes():
    global channels_list, guilds_index, users_list
    channel_stats = df.groupby("channel_id").agg(
        channel_name=("channel_name", "first"),
        guild_id=("guild_id", "first"),
        message_count=("message_id", "count")
    ).reset_index()
    channel_stats = channel_stats.sort_values("message_count", ascending=False)
    channels_list = channel_stats.to_dict(orient="records")

    guilds_index = []
    for ch in channels_list:
        ch["guild_id"] = str(ch["guild_id"])
    for gid in sorted({ch["guild_id"] for ch in channels_list},
                      key=lambda g: -sum(c["message_count"] for c in channels_list if c["guild_id"] == g)):
        g_channels = [ch for ch in channels_list if ch["guild_id"] == gid]
        guilds_index.append({
            "guild_id": gid,
            "name": guild_display_name(gid),
            "message_count": int(sum(c["message_count"] for c in g_channels)),
            "channel_count": len(g_channels),
            "categories": categorize_channels(g_channels),
        })

    user_counts = df["author"].value_counts() if len(df) else pd.Series(dtype=int)
    users_list = [{"name": str(k), "count": int(v)} for k, v in user_counts.items()]
